mapper.select:
SELECT SUM(reject_num) rejectNum,SUM(monitor_num) monitorNum,SUM(c2s_pkt_num) c2sPktNum,SUM(s2c_pkt_num) s2cPktNum,SUM(c2s_byte_len) c2sByteLen,SUM(s2c_byte_len) s2cByteLen,SUM(new_uni_conn_num) newUniConnNum,SUM(live_conn_num) liveConnNum,
SUM(drop_conn_num) dropConnNum,SUM(loop_conn_num) loopConnNum FROM ntc_total_report
where report_time = #{reportTime}

select IFNULL(p.gbps,0) gbps,IFNULL(p.pps,0) pps,IFNULL(p.sumNum,0) linkNum, date_format(a.min5,'%Y-%m-%d %H:%i') time from (select date_sub(#{statTime},interval @mycnt :=@mycnt + 5 MINUTE) min5 from (SELECT @mycnt:=-5) m, traffic_trans_statistic limit 12) a LEFT JOIN ( SELECT date_format(stat_time, '%Y-%m-%d %H:%i') timestamp, SUM(link_num)/300 sumNum, SUM(c2s_pkt_num+s2c_pkt_num)/300 AS pps, (SUM(c2s_byte_len+s2c_byte_len)*8/300/1024/1024/1024) AS gbps FROM traffic_trans_statistic
and addr_type=#{addrType}
and trans_type=${transType}
AND stat_time > DATE_SUB(#{statTime,jdbcType=TIMESTAMP}, INTERVAL 1 HOUR)
GROUP by timestamp ) p on date_format(p.timestamp,'%Y-%m-%d %H:%i')=date_format(a.min5,'%Y-%m-%d %H:%i') ORDER by time
